   19	// The one surviving situation for invariant:NAKED_BESIDE_WALLED after the QUAL-DEDUP merge: a naked
   20	// colony, a naked planet and a stationary fleet, each read at the bound and at zero. The live read
   21	// found accounts with planets at zero defence while a sibling held a real wall: the whole wall was
   22	// raised on the planet with the most to lose and the bare siblings were never reached.
   23	test('a login gives the bare sibling the wall the account already holds elsewhere', function (): void {
   24	    $situation = Situation::of($this)
   25	        ->levelEveryPlanet('robot_factory', 2)
   26	        ->levelEveryPlanet('shipyard', 4)
   27	        ->defence('rocket_launcher', 20)
   28	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   29	        ->session();
   30	
   31	    $bare = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   32	        ->whereKeyNot($this->currentPlanetId)->value('id');
   33	    $planet = app(PlanetServiceFactory::class)->make((int) $bare, true);
   34	
   35	    $situation->expectWork(AiWorkKind::QueueUnits);
   36	
   37	    // A short build may already be complete by the time the session's own clock has advanced to every
   38	    // intent, so the wall counts whether it is standing or still paid for in the yard.
   39	    expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account());
   40	});
   41	
   42	// QUAL-003's live shape (invariant:NAKED_BESIDE_WALLED, aspect:shipyard), the story the deleted
   43	// NakedColonyWallSituationTest held: the colony below the yard its wall waits on. The cohort read
   44	// found an account holding a wall on one planet while a young colony stood at zero defence: the wall
   45	// waits on a shipyard the colony does not have yet, and the account kept spending its yard elsewhere.
   46	// An account whose sibling already holds a wall has to bring the shipyard and then the wall to the
   47	// bare colony, instead of leaving it naked for as long as it plays.
   48	test('an account whose sibling holds a wall reaches the colony that has no shipyard yet', function (): void {
   49	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
   50	
   51	    $situation = Situation::of($this)
   52	        ->level('robot_factory', 2)
   53	        ->level('shipyard', 4)
   54	        ->defence('rocket_launcher', 30)
   55	        ->colony()
   56	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   57	        ->sessions(8, 30);
   58	
   59	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   60	        ->whereNotIn('id', $before)->value('id');
   61	    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);
   62	
   63	    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'expected the wall on the colony that started without a shipyard; ' . $situation->account());
   64	});
   65	
   66	// The story the deleted StationaryFleetWallSituationTest held: what a planet stands to lose is not only
   67	// the output that piles up while the account is away. A fleet left standing in orbit is worth to a
   68	// raider exactly what the pile is, so a wall sized on production alone leaves it uncovered. The plant
   69	// puts the idle fleet on a planet whose small wall already covers the mines, and the record must state
   70	// a need only once the fleet is there.
   71	test('an idle fleet raises what the planet stands to lose', function (): void {
   72	    $situation = Situation::of($this)
   73	        ->resources(1_000_000, 1_000_000, 1_000_000)
   74	        ->level('shipyard', 4)
   75	        ->defence('rocket_launcher', 200);
   76	
   77	    $player = $this->planetService->getPlayer();
   78	    $covered = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
   79	
   80	    expect($covered)->toBeNull('the wall already covers production-only exposure; ' . $situation->account());
   81	
   82	    $situation->ships('light_fighter', 2_000);
   83	
   84	    $exposed = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
   85	
   86	    expect($exposed)->toBeInstanceOf(DefenseNeed::class)
   87	        ->and($exposed->protectedValue)->toBeGreaterThan(0.0)
   88	        ->and($exposed->currentDefenseValue)->toBeGreaterThan(0.0);
   89	});
   90	
   91	// The bound at zero of the fleet rule: the fleet only adds to the exposure, it is not what creates the
   92	// need. A planet whose own output is nothing still takes the file's floor, so an account is not left
   93	// naked because it has no fleet to protect.
   94	test('a planet with nothing standing in orbit still takes the doctrine floor', function (): void {
   95	    resolve(SettingsService::class)->set('economy_speed', 1);
   96	
   97	    Situation::of($this)
   98	        ->resources(1_000_000, 1_000_000, 1_000_000)
   99	        ->level('shipyard', 4)
  100	        ->level('metal_mine', 0)
  101	        ->level('crystal_mine', 0)
  102	        ->level('deuterium_synthesizer', 0);
  103	
  104	    $this->planetService->updateResourceProductionStats();
  105	
  106	    $need = app(DefenseNeedEvaluator::class)->evaluate($this->planetService->getPlayer(), $this->planetService);
  107	
  108	    expect($need)->toBeInstanceOf(DefenseNeed::class)
  109	        ->and($need->reason)->toBe('defense:need:minimum-deterrent');
  110	});
