  112	// The bound on the other side: a planet that already holds a wall is not the account's next wall order,
  113	// so one login serves the bare sibling instead of stacking yet another batch on the walled planet.
  114	test('a login does not spend its wall order on the planet that already holds one', function (): void {
  115	    $situation = Situation::of($this)
  116	        ->levelEveryPlanet('robot_factory', 2)
  117	        ->levelEveryPlanet('shipyard', 4)
