  128	// The invariant counts the account, not the planet (player 51: one planet holding 1,496 units, others
  129	// naked), so a full day of the account's own logins must leave no sibling at zero defence.
  130	test('an account whose homeworld holds a wall leaves no sibling naked', function (): void {
  131	    $situation = Situation::of($this)
