  145	// A walled homeworld moves the bare sibling before the sibling's own habits, so one login already
  146	// turns to the yard the sibling needs rather than leaving it for a later day. The sibling's yard is
  147	// below the wall's unit, so the order it takes is the facility the wall waits on.
  148	test('a login beside a walled homeworld turns to the bare sibling', function (): void {
  149	    $situation = Situation::of($this)
  150	        ->resources(50_000_000, 50_000_000, 50_000_000)
