  159	
  160	    foreach (nakedPlanets($this->currentUserId) as $planetId) {
  161	        $ordered = BuildingQueue::query()->where('planet_id', $planetId)->where('canceled', 0)->exists();
  162	        expect($ordered)->toBeTrue('the bare sibling got no order this login; ' . $situation->account());
  163	    }
  164	});
