  166	// The zero case of the rule: the invariant names a naked planet *beside a walled sibling*. A lone
  167	// planet has no sibling, so nothing hoists the wall for it -- it takes the ordinary floor.
  168	test('a one-planet account is walled without a sibling to point at', function (): void {
  169	    $situation = Situation::of($this)
  170	        ->resources(50_000_000, 50_000_000, 50_000_000)
