15	// QUAL-003 (invariant:NAKED_BESIDE_WALLED, aspect:shipyard): the live read counts the defence
16	// columns the host has *built* on every planet of an account and cries wolf when one stands at zero
17	// while a sibling already holds a real wall. The module's orders have to survive a whole day of the
18	// account's own logins, so this mirrors the cohort's read after that day rather than only checking
19	// the orders one login placed.
20	test('a day of an account with a walled homeworld leaves no colony at zero built defence', function (): void {
21	    $situation = Situation::of($this)
22	        ->resources(50_000_000, 50_000_000, 50_000_000)
23	        ->level('robot_factory', 2)
24	        ->level('shipyard', 4)
25	        ->defence('rocket_launcher', 60)
26	        ->colony()
27	        ->colony()
28	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000);
29	
30	    $situation->day();
31	
32	    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());
33	
34	    foreach (Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)->pluck('id') as $planetId) {
35	        $row = (array) DB::table('planets')->where('id', (int) $planetId)->first();
36	        $built = 0;
37	        foreach ($defence as $machineName) {
38	            $built += (int) ($row[$machineName] ?? 0);
39	        }
40	
41	        expect($built)->toBeGreaterThan(0, 'planet ' . $planetId . ' holds no built defence after a day; ' . $situation->account());
42	    }
43	
44	    // The built units are nothing the host invented: the account's own defence stands on every planet.
45	    $standing = 0;
46	    foreach (Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)->pluck('id') as $planetId) {
47	        $standing += app(DefenseNeedEvaluator::class)->standingUnits(app(PlanetServiceFactory::class)->make((int) $planetId, true));
48	    }
49	
50	    expect($standing)->toBeGreaterThan(0);
51	});

