221	/** @return list<int> the account's planets (moons excluded) whose built defence columns are all zero */
222	function builtNakedPlanets(int $playerId): array
223	{
224	    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());
225	
226	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
227	        ->map(static fn ($id): int => (int) $id)
228	        ->filter(static function (int $id) use ($defence): bool {
229	            $row = (array) DB::table('planets')->where('id', $id)->first();
230	            foreach ($defence as $machineName) {
231	                if ((int) ($row[$machineName] ?? 0) > 0) {
232	                    return false;
233	                }
234	            }
235	
236	            return true;
237	        })->values()->all();
238	}
