240	/** @return list<int> the account's planets (moons excluded) that hold no defence, ordered or built */
241	function nakedPlanets(int $playerId): array
242	{
243	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
244	        ->map(static fn ($id): int => (int) $id)
245	        ->filter(static function (int $id): bool {
246	            $planet = app(PlanetServiceFactory::class)->make($id, true);
247	
248	            return $planet === null || app(DefenseNeedEvaluator::class)->standingUnits($planet) === 0;
249	        })->values()->all();
250	}
