252	/** The defence units the account stands on its planets. */
253	function standingDefence(int $playerId): int
254	{
255	    $total = 0;
256	
257	    foreach (Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id') as $planetId) {
258	        $planet = app(PlanetServiceFactory::class)->make((int) $planetId, true);
259	        $total += $planet === null ? 0 : $planet->getDefenseUnits()->getAmount();
260	    }
261	
262	    return $total;
263	}

