  438	    /**
  439	     * The facilities the host's own smallest defence unit requires, or none when this planet does not
  440	     * need them.
  441	     *
  442	     * A planet needs them exactly when it holds no defence while a sibling of the same account
  443	     * already stands one: that is the account past its opening, with a wall it built everywhere it
  444	     * could reach, so the reasons the unit planner has for waiting no longer apply and the facility
  445	     * that gates the wall is as much a prerequisite as a laboratory gating a technology.
  446	     *
  447	     * @return array<string, int>
  448	     */
  449	    private function wallPrerequisites(PlanetService $planet): array
  450	    {
  451	        if (! $this->nakedBesideWalled($planet)) {
  452	            return [];
  453	        }
  454	
  455	        $unit = $this->smallestDefenceUnit();
  456	
