  460	    /**
  461	     * Whether this planet holds nothing while a sibling of the same account holds something.
  462	     *
  463	     * "Holds" is the unit planner's own answer -- built plus already paid for in the yard -- and not the
  464	     * built-only count: the account has left its opening the moment its first wall order is placed, so the
  465	     * sibling's bare neighbour is reached from that login rather than one login behind a wall that is
  466	     * already standing in the queue (QUAL-003: the two planners disagreed about when a wall stands).
  467	     */
  468	    private function nakedBesideWalled(PlanetService $planet): bool
  469	    {
  470	        $defence = app(DefenseNeedEvaluator::class);
  471	
  472	        if ($defence->standingUnits($planet) > 0) {
  473	            return false;
  474	        }
  475	
  476	        $player = $planet->getPlayer();
  477	        if ($player === null) {
  478	            return false;
  479	        }
  480	
  481	        foreach ($player->planets->all() as $sibling) {
  482	            if ($sibling->getPlanetId() !== $planet->getPlanetId() && $defence->standingUnits($sibling) > 0) {
  483	                return true;
  484	            }
  485	        }
  486	
  487	        return false;
  488	    }
